text:
Here's how you could write a simple sunset using the p5.brush library:

```javascript
let hills = [];
let someColor;

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
  for (let i = 0; i < 1000; i++) {
    hills.push(random(0, 400));
    someColor = color(random(0, 255), random(0, 255), random(0, 255));
  }
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  fill(0, 0, 0);
  for (let i = 0; i < hills.length; i++) {
    fill(someColor);
    brush.b3d(grid(
      hills[i],
      hills[1000],
      hills[i + 100]
    ));
  }
}
```

