function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  fill("##e08a72", 150);
  fillBleed(0.1);
  for (let i = 0; i < 100; i++) {
    let x = random(0, 400);
    let y = random(0, 400);
    let r = random(5, 20);
    let c = colorHSV(sin(i / 200), 1, sin(i / 100));
    fill(c, 150);
    circle(x, y, r);
    brush.beginShape(1.5);
    brush.vertex(x, y);
    brush.endShape(true);
  }

  // Hills
  fill("#3d0028");
  for (let i = 0; i < 40; i++) {
    let r = random(30, 60);
    circle(random(0, 400), random(0, 400), r);
    brush.beginShape(0.6);
    brush.vertex(random(0, 400), random(0, 400));
    brush.endShape(true);
  }

  // Ground
  fill("#1e1e1e");
  for (let i = 0; i < 400; i++) {
    circle(i, 0, random(0, 40));
  }
}
