Create a sunset sky over the hills with `fillTexture` to draw soft gradients over the hills.

```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  brush.fill("lightskyblue", 1);
  brush.fillTexture(0.5, 0.8);
  brush.vertex(0, 0);
  brush.vertex(0, 200);
  brush.vertex(200, 200);
  brush.vertex(400, 0);
  brush.endShape(true);

  brush.fill("dodgerblue", 1);
  brush.fillTexture(0.75, 0.8);
  brush.vertex(0, 400);
  brush.vertex(400, 400);
  brush.vertex(200, 200);
  brush.vertex(200, 0);
  brush.endShape(true);

  brush.fill("#0f120f", 0.2);
  brush.fillTexture(0.5, 0.8);
  brush.vertex(0, 200);
  brush.vertex(200, 200);
  brush.vertex(200, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  brush.fill("#005c5c", 0.2);
  brush.fillTexture(0.5, 0.8);
  brush.vertex(200, 200);
  brush.vertex(200, 400);
  brush.vertex(400, 200);
  brush.vertex(0, 0);
  brush.endShape(true);

  brush.fill("#6495ed", 1);
  brush.fillTexture(0.5, 0.8);
  brush.vertex(0, 200);
  brush.vertex(0, 400);
  brush.vertex(400, 200);
  brush.vertex(200, 0);
  brush.endShape(true);
}
